      for (kk = 0; kk < _PB_M; kk += TS) {
        kmax = kk + TS - 1;
        if (kmax >= _PB_M) kmax = _PB_M - 1;
        for (j = jj; j <= jmax; j++) {
          cij = C[i][j];
          #pragma omp simd reduction(+:cij)
          for (k = kk; k <= kmax; k++)
